-- 28/10/2026: LEP art. 52, Aplicação prática no formato de orientação de uso (pipeline de comentários).
-- Revisão independente em 3 rodadas (a 3ª aberta com autorização da Jessica): rodada 3, revisores A e B CORRETO, sem ARRISCADO, sem genérico.
-- Resultado: 'corrigido'. md5(aplicacao_pratica) esperado: ca9d2e3f7389d5bdd6771692a8a7f2a9
-- Art. 112 NÃO entra: o revisor B deu IMPRECISO (omissão de 'mulher' no § 3º) e o A marcou genérico; segue com o comentário antigo e sem selo.
-- Rodar os dois updates como comandos separados, no SQL Editor (o conector cancela UPDATE).
update legislacao set aplicacao_pratica =
  'Ao examinar o regime disciplinar diferenciado, confira qual hipótese é invocada: a prática de fato previsto como crime doloso, que constitui falta grave e, quando ocasionar subversão da ordem ou disciplina internas, sujeita o preso ao regime (caput); o alto risco para a ordem e a segurança do estabelecimento penal ou da sociedade (§ 1º, inciso I); as fundadas suspeitas de envolvimento ou participação em organização criminosa, associação criminosa ou milícia privada, independentemente da prática de falta grave (§ 1º, inciso II); ou, para quem tenha cometido crime de violência doméstica e familiar contra a mulher, a ameaça ou a violência contra a vítima ou seus familiares (§ 8º). Na peça, relacione os fatos do caso a essa hipótese e demonstre se há ou não elementos que a sustentem. '
  || 'Confira também as características dos incisos I a VII, por exemplo: duração máxima de até 2 (dois) anos, sem prejuízo de repetição da sanção por nova falta grave de mesma espécie (inciso I); recolhimento em cela individual (inciso II); entrevistas sempre monitoradas, exceto com o defensor, salvo expressa autorização judicial em contrário (inciso V). Elas servem de parâmetro para verificar se o regime cumprido corresponde ao que a lei descreve. A visita do inciso III será gravada, com autorização judicial, e acompanhada por policial penal (§ 6º); após os primeiros 6 (seis) meses, quem não a receber poderá, após prévio agendamento, ter contato telefônico gravado com uma pessoa da família, 2 (duas) vezes por mês e por 10 (dez) minutos (§ 7º). '
  || 'Havendo indícios de liderança em organização criminosa, associação criminosa ou milícia privada, ou de atuação criminosa em 2 (dois) ou mais Estados da Federação, o regime será obrigatoriamente cumprido em estabelecimento prisional federal (§ 3º). Na prorrogação, por períodos de 1 (um) ano, verifique se constam os indícios descritos nos incisos I e II do § 4º. A inclusão pode ser solicitada ao juiz pelo diretor do estabelecimento, por outra autoridade administrativa ou pelo Ministério Público (§ 10).'
where codigo = 'lep' and numero = 52 and paragrafo is null and inciso is null and vigente and coalesce(titulo, '') = '';

update legislacao set comentario_conferencia = 'revisao_independente', comentario_resultado = 'corrigido', comentario_conferido_em = current_date
where codigo = 'lep' and numero = 52 and paragrafo is null and inciso is null and vigente and coalesce(titulo, '') = '';

select md5(aplicacao_pratica), comentario_conferencia, comentario_resultado from legislacao where codigo = 'lep' and numero = 52 and paragrafo is null and inciso is null;
